#include <cstddef>
#include <cstring>

namespace leveldb {

class Slice {
public:
    Slice() : data_(""), size_(0) {}
    Slice(const char* d, size_t n) : data_(d), size_(n) {}

    const char* data() const { return data_; }
    size_t size() const { return size_; }

private:
    const char* data_;
    size_t size_;
};

size_t CalculateSharedPrefix(const Slice& a, const Slice& b) {
    const size_t min_len = (a.size() < b.size()) ? a.size() : b.size();
    const char* a_data = a.data();
    const char* b_data = b.data();

    for (size_t i = 0; i < min_len; ++i) {
        if (a_data[i] != b_data[i]) {
            return i;
        }
    }
    return min_len;
}

} // namespace leveldb

int main() {
    leveldb::Slice a("hello world", 11);
    leveldb::Slice b("hello there", 11);
    leveldb::Slice c("hello", 5);
    leveldb::Slice d("world", 5);

    size_t result1 = leveldb::CalculateSharedPrefix(a, b); // should be 6 ("hello ")
    size_t result2 = leveldb::CalculateSharedPrefix(a, c); // should be 5 ("hello")
    size_t result3 = leveldb::CalculateSharedPrefix(a, d); // should be 0 (no prefix)

    return (result1 == 6 && result2 == 5 && result3 == 0) ? 0 : 1;
}

